WITH flagged AS (SELECT *, CASE WHEN reading_ts - LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) > INTERVAL '15' MINUTE THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), islands AS (SELECT id, device_code, reading_ts, humidity, pressure, firmware, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT CASE WHEN island_id >= 9 THEN 'PREMIUM' ELSE 'STANDARD' END AS island_id_tier, PERCENTILE_APPROX(humidity, 0.9) AS humidity_p90, MAX(humidity) FILTER (WHERE device_code = 'DV-03') AS dv_03_max_humidity FROM islands GROUP BY 1 ORDER BY humidity_p90 DESC;
